// Status Badge Component
function StatusBadge({ status }: { status: string }) {
    const styles = {
        active: 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20',
        trial: 'bg-amber-500/10 text-amber-400 border-amber-500/20',
        suspended: 'bg-rose-500/10 text-rose-400 border-rose-500/20',
        cancelled: 'bg-gray-500/10 text-gray-400 border-gray-500/20',
    };

    return (
        <span className={`inline-flex items-center gap-1 rounded-full border px-2.5 py-0.5 text-xs font-medium capitalize ${styles[status as keyof typeof styles] || styles.cancelled}`}>
            <span className={`h-1.5 w-1.5 rounded-full ${status === 'active' ? 'bg-emerald-400 animate-pulse' : status === 'trial' ? 'bg-amber-400' : 'bg-gray-400'}`} />
            {status}
        </span>
    );
}

// Plan Badge
function PlanBadge({ plan }: { plan: string }) {
    const styles = {
        Enterprise: 'bg-gradient-to-r from-purple-500 to-indigo-600',
        Professional: 'bg-gradient-to-r from-blue-500 to-cyan-600',
        Starter: 'bg-gradient-to-r from-gray-500 to-gray-600',
    };

    return (
        <span className={`rounded-md px-2 py-0.5 text-xs font-medium text-white ${styles[plan as keyof typeof styles] || styles.Starter}`}>
            {plan}
        </span>
    );
}

export default function TenantsPage() {
    const [searchQuery, setSearchQuery] = useState('');
    const [statusFilter, setStatusFilter] = useState('all');
    const [selectedTenants, setSelectedTenants] = useState<string[]>([]);

    const filteredTenants = mockTenants.filter(tenant => {
        const matchesSearch = tenant.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
            tenant.domain.toLowerCase().includes(searchQuery.toLowerCase()) ||
            tenant.ownerEmail.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesStatus = statusFilter === 'all' || tenant.status === statusFilter;
        return matchesSearch && matchesStatus;
    });

    const toggleSelectAll = () => {
        if (selectedTenants.length === filteredTenants.length) {
            setSelectedTenants([]);
        } else {
            setSelectedTenants(filteredTenants.map(t => t.id));
        }
    };

    const toggleSelect = (id: string) => {
        setSelectedTenants(prev =>
            prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
        );
    };

    return (
        <div className="space-y-6 animate-fade-in">
            {/* Page Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold text-white">Tenants</h1>
                    <p className="text-sm text-gray-400">Manage all platform tenants and their stores</p>
                </div>
                <Link
                    href="/dashboard/tenants/new"
                    className="flex items-center gap-2 rounded-xl bg-gradient-to-r from-indigo-500 to-purple-600 px-4 py-2.5 text-sm font-medium text-white shadow-lg shadow-indigo-500/25 hover:shadow-xl hover:shadow-indigo-500/30 transition-all"
                >
                    <Plus className="h-4 w-4" />
                    New Tenant
                </Link>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <div className="rounded-xl bg-white/5 border border-white/10 p-4">
                    <p className="text-2xl font-bold text-white">{mockTenants.length}</p>
                    <p className="text-sm text-gray-400">Total Tenants</p>
                </div>
                <div className="rounded-xl bg-white/5 border border-white/10 p-4">
                    <p className="text-2xl font-bold text-emerald-400">{mockTenants.filter(t => t.status === 'active').length}</p>
                    <p className="text-sm text-gray-400">Active</p>
                </div>
                <div className="rounded-xl bg-white/5 border border-white/10 p-4">
                    <p className="text-2xl font-bold text-amber-400">{mockTenants.filter(t => t.status === 'trial').length}</p>
                    <p className="text-sm text-gray-400">On Trial</p>
                </div>
                <div className="rounded-xl bg-white/5 border border-white/10 p-4">
                    <p className="text-2xl font-bold text-rose-400">{mockTenants.filter(t => t.status === 'suspended').length}</p>
                    <p className="text-sm text-gray-400">Suspended</p>
                </div>
            </div>

            {/* Filters & Actions */}
            <div className="flex flex-col md:flex-row gap-4 items-start md:items-center justify-between">
                <div className="flex gap-3 w-full md:w-auto">
                    {/* Search */}
                    <div className="relative flex-1 md:w-80">
                        <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-500" />
                        <input
                            type="text"
                            placeholder="Search tenants..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="h-10 w-full rounded-lg bg-white/5 pl-10 pr-4 text-sm text-white placeholder-gray-500 border border-white/10 focus:border-indigo-500 focus:outline-none focus:ring-1 focus:ring-indigo-500"
                        />
                    </div>

                    {/* Status Filter */}
                    <select
                        value={statusFilter}
                        onChange={(e) => setStatusFilter(e.target.value)}
                        className="h-10 rounded-lg bg-white/5 px-3 text-sm text-gray-300 border border-white/10 focus:border-indigo-500 focus:outline-none"
                    >
                        <option value="all">All Status</option>
                        <option value="active">Active</option>
                        <option value="trial">Trial</option>
                        <option value="suspended">Suspended</option>
                    </select>
                </div>

                {/* Bulk Actions */}
                {selectedTenants.length > 0 && (
                    <div className="flex items-center gap-2">
                        <span className="text-sm text-gray-400">{selectedTenants.length} selected</span>
                        <button className="px-3 py-1.5 rounded-lg bg-amber-500/10 text-amber-400 text-sm hover:bg-amber-500/20">
                            Suspend
                        </button>
                        <button className="px-3 py-1.5 rounded-lg bg-rose-500/10 text-rose-400 text-sm hover:bg-rose-500/20">
                            Delete
                        </button>
                    </div>
                )}

                <button className="flex items-center gap-2 px-3 py-2 rounded-lg bg-white/5 border border-white/10 text-sm text-gray-300 hover:bg-white/10">
                    <Download className="h-4 w-4" />
                    Export
                </button>
            </div>

            {/* Table */}
            <div className="rounded-2xl bg-white/5 border border-white/10 overflow-hidden">
                <table className="w-full">
                    <thead>
                        <tr className="border-b border-white/10">
                            <th className="px-4 py-3 text-left">
                                <input
                                    type="checkbox"
                                    checked={selectedTenants.length === filteredTenants.length && filteredTenants.length > 0}
                                    onChange={toggleSelectAll}
                                    className="h-4 w-4 rounded border-white/20 bg-white/5 text-indigo-500 focus:ring-indigo-500 focus:ring-offset-0"
                                />
                            </th>
                            <th className="px-4 py-3 text-left text-xs font-medium text-gray-400 uppercase tracking-wider">Tenant</th>
                            <th className="px-4 py-3 text-left text-xs font-medium text-gray-400 uppercase tracking-wider">Plan</th>
                            <th className="px-4 py-3 text-left text-xs font-medium text-gray-400 uppercase tracking-wider">Status</th>
                            <th className="px-4 py-3 text-left text-xs font-medium text-gray-400 uppercase tracking-wider">MRR</th>
                            <th className="px-4 py-3 text-left text-xs font-medium text-gray-400 uppercase tracking-wider">Products</th>
                            <th className="px-4 py-3 text-left text-xs font-medium text-gray-400 uppercase tracking-wider">Orders</th>
                            <th className="px-4 py-3 text-left text-xs font-medium text-gray-400 uppercase tracking-wider">Created</th>
                            <th className="px-4 py-3 text-right text-xs font-medium text-gray-400 uppercase tracking-wider">Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {filteredTenants.map((tenant) => (
                            <tr key={tenant.id} className="border-b border-white/5 hover:bg-white/5 transition-colors">
                                <td className="px-4 py-4">
                                    <input
                                        type="checkbox"
                                        checked={selectedTenants.includes(tenant.id)}
                                        onChange={() => toggleSelect(tenant.id)}
                                        className="h-4 w-4 rounded border-white/20 bg-white/5 text-indigo-500 focus:ring-indigo-500 focus:ring-offset-0"
                                    />
                                </td>
                                <td className="px-4 py-4">
                                    <div className="flex items-center gap-3">
                                        <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-gradient-to-br from-indigo-500 to-purple-600">
                                            <Building2 className="h-5 w-5 text-white" />
                                        </div>
                                        <div>
                                            <Link href={`/dashboard/tenants/${tenant.id}`} className="text-sm font-medium text-white hover:text-indigo-400">
                                                {tenant.name}
                                            </Link>
                                            <p className="text-xs text-gray-500">{tenant.domain}</p>
                                        </div>
                                    </div>
                                </td>
                                <td className="px-4 py-4">
                                    <PlanBadge plan={tenant.plan} />
                                </td>
                                <td className="px-4 py-4">
                                    <StatusBadge status={tenant.status} />
                                </td>
                                <td className="px-4 py-4 text-sm text-white font-medium">
                                    ${tenant.mrr}
                                </td>
                                <td className="px-4 py-4 text-sm text-gray-300">
                                    {tenant.products.toLocaleString()}
                                </td>
                                <td className="px-4 py-4 text-sm text-gray-300">
                                    {tenant.orders.toLocaleString()}
                                </td>
                                <td className="px-4 py-4 text-sm text-gray-400">
                                    {new Date(tenant.createdAt).toLocaleDateString()}
                                </td>
                                <td className="px-4 py-4 text-right">
                                    <div className="flex items-center justify-end gap-1">
                                        <button className="p-2 rounded-lg hover:bg-white/10 text-gray-400 hover:text-white" title="View">
                                            <Eye className="h-4 w-4" />
                                        </button>
                                        <button className="p-2 rounded-lg hover:bg-white/10 text-gray-400 hover:text-white" title="Visit Store">
                                            <ExternalLink className="h-4 w-4" />
                                        </button>
                                        <button className="p-2 rounded-lg hover:bg-white/10 text-gray-400 hover:text-white" title="More">
                                            <MoreHorizontal className="h-4 w-4" />
                                        </button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>

                {/* Pagination */}
                <div className="flex items-center justify-between px-4 py-3 border-t border-white/5">
                    <p className="text-sm text-gray-400">
                        Showing <span className="font-medium text-white">{filteredTenants.length}</span> of{' '}
                        <span className="font-medium text-white">{mockTenants.length}</span> tenants
                    </p>
                    <div className="flex gap-2">
                        <button className="px-3 py-1.5 rounded-lg bg-white/5 text-sm text-gray-400 hover:bg-white/10 disabled:opacity-50" disabled>
                            Previous
                        </button>
                        <button className="px-3 py-1.5 rounded-lg bg-indigo-500 text-sm text-white">
                            1
                        </button>
                        <button className="px-3 py-1.5 rounded-lg bg-white/5 text-sm text-gray-400 hover:bg-white/10">
                            Next
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
}
